import { readdirSync, readFileSync } from 'fs';
import { join } from 'path';

const dir = 'wiki/npcs';
const files = readdirSync(dir).filter(f => f.endsWith('.md'));
const rows: any[] = [];
for (const f of files) {
  const t = readFileSync(join(dir, f), 'utf8');
  const cl = t.match(/\*\*Combat Level\*\* \| ([\d\-]+)/);
  const hp = t.match(/\*\*Hitpoints\*\* \| ([\d\-]+)/);
  const def = (name: string) => {
    const m = t.match(new RegExp(`\\*\\*${name} Defence\\*\\* \\| (-?\\d+)`));
    return m ? Number(m[1]) : null;
  };
  const atkB = t.match(/\*\*Attack Bonus\*\* \| (-?\d+)/);
  const strB = t.match(/\*\*Strength Bonus\*\* \| (-?\d+)/);
  const stab = def('Stab'), slash = def('Slash'), crush = def('Crush');
  if (!cl) continue;
  const clNum = Number(cl[1]);
  const hpNum = hp ? Number(hp[1]) : 0;
  if (clNum < 25) continue;
  const bestDef = Math.min(...[stab, slash, crush].filter((x): x is number => x !== null));
  rows.push({ name: f.replace('.md', ''), cl: clNum, hp: hpNum, stab, slash, crush, bestDef,
    atkB: atkB ? Number(atkB[1]) : null, strB: strB ? Number(strB[1]) : null });
}
// rank: high cl, low def, low attack bonus
rows.sort((a, b) => b.cl - a.cl);
for (const r of rows) {
  console.log(`${r.name.padEnd(30)} CL${String(r.cl).padStart(3)} HP${String(r.hp).padStart(3)} def[${r.stab}/${r.slash}/${r.crush}] atkB${r.atkB} strB${r.strB}`);
}

