let st=sdk.getState();
const hobs = st?.nearbyNpcs?.filter(n=>/hobgoblin/i.test(n.name))||[];
const target = hobs.sort((a,b)=>a.distance-b.distance)[0];
let res={pos:`${st?.player?.worldX},${st?.player?.worldZ}`, hobs:hobs.map(h=>`${h.name}(${h.combatLevel}) HP:${h.hp}/${h.maxHp} d${h.distance}`)};
if(target){ try{ const a=await bot.attack(target,3000); res.atk=a.success; }catch(e){ res.atkerr=String(e);} }
const log=[];
for(let i=0;i<30;i++){ await sdk.waitForTicks(2); const s=sdk.getState(); const h=s?.nearbyNpcs?.find(n=>/hobgoblin/i.test(n.name)); log.push(`${s?.tick} hp${s?.player?.hp} hob${h?.hp} cmb${s?.player?.combat?.inCombat}`); if(s?.player?.isDead){log.push('DIED');break;} }
return {res, log, players:sdk.getNearbyPlayers().map(p=>`${p.name}(${p.combatLevel})`)};

await sdk.sendSetCombatStyle(2);
const end=Date.now()+180000; const startTick=sdk.getState()?.tick??0; let atks=0, l42=0;
while(Date.now()<end){
  const st=sdk.getState();
  if(!st || st.player?.isDead){ await sdk.waitForTicks(3); continue; }
  const hobs=st.nearbyNpcs.filter(n=>/hobgoblin/i.test(n.name))
    .filter(n=>n.optionsWithIndex.some(o=>/attack/i.test(o.text)));
  if(!hobs.length){ await sdk.waitForTicks(2); continue; }
  const t=hobs.sort((a,b)=> (b.combatLevel-a.combatLevel) || (a.distance-b.distance))[0];
  if(t.combatLevel>=40) l42++;
  try{ const r=await bot.attack(t,3500); if(r.success) atks++; }catch(e){ await sdk.waitForTicks(1); }
}
const st=sdk.getState();
return { atks, l42targets:l42, elapsed:(st?.tick??0)-startTick, combat:st?.player?.combatLevel, hp:st?.player?.maxHp,
  skills:st?.skills?.filter(s=>['Attack','Strength','Defence','Hitpoints'].includes(s.name)).map(s=>`${s.name}:${s.level}`) };

const END=Date.now()+300000; let atks=0, walks=0, deaths=0; let lastLife=sdk.getState()?.player?.lifeId;
let styleSet=false;
while(Date.now()<END){
  let st=sdk.getState();
  if(!st){ await sdk.waitForTicks(2); continue; }
  if((st.player?.lifeId??0)!==lastLife){ deaths++; lastLife=st.player?.lifeId; }
  if(!sdk.findEquipmentItem(/bronze sword/i)){ try{ await bot.equipItem(/bronze sword/i);}catch{} try{ await bot.equipItem(/wooden shield/i);}catch{} }
  if(!styleSet){ try{ await sdk.sendSetCombatStyle(2); styleSet=true; }catch{} }
  const nearHobs = st.nearbyNpcs.some(n=>/hobgoblin/i.test(n.name));
  if(!nearHobs){ try{ await bot.walkTo(2905,3295,4,{timeout:50000}); walks++; }catch{} await sdk.waitForTicks(2); continue; }
  const hobs=st.nearbyNpcs.filter(n=>/hobgoblin/i.test(n.name)).filter(n=>n.optionsWithIndex.some(o=>/attack/i.test(o.text)));
  if(!hobs.length){ await sdk.waitForTicks(2); continue; }
  const t=hobs.sort((a,b)=>(b.combatLevel-a.combatLevel)||(a.distance-b.distance))[0];
  try{ const r=await bot.attack(t,3500); if(r.success) atks++; }catch{ await sdk.waitForTicks(1); }
}
const st=sdk.getState();
return { atks, walks, deaths, combat:st?.player?.combatLevel, hp:st?.player?.maxHp,
  pos:`${st?.player?.worldX},${st?.player?.worldZ}`,
  skills:st?.skills?.filter(s=>['Attack','Strength','Defence','Hitpoints'].includes(s.name)).map(s=>`${s.name}:${s.level}`) };

